package com.alan.thormonitor;
import android.app.*;import android.content.*;import android.os.*;import android.text.InputType;import android.widget.*;import java.util.*;
final class HostWebOpsView extends LinearLayout {
 private final Activity activity;private final HostStatsUi ui;private final TextView status;private final Button start;private final EditText user,password,confirm;private boolean saving;
 HostWebOpsView(Activity a){super(a);activity=a;ui=new HostStatsUi(a);setOrientation(VERTICAL);addView(ui.text("Web Ops",28,true));ui.gap(this,16);
  LinearLayout server=card("Browser access");server.addView(ui.muted("Use a browser on your local network or private VPN.",16));status=ui.text("",17,false);ui.gap(server,12);server.addView(status);ui.gap(server,12);
  start=ui.button("",()->{boolean enable=!WebOps.enabled(a);WebOps.prefs(a).edit().putBoolean("enabled",enable).apply();if(enable&&!MonitorService.running){a.getSharedPreferences("monitor",0).edit().putBoolean("monitor_wanted",true).apply();a.startForegroundService(new Intent(a,MonitorService.class));}new Thread(()->{if(enable)WebOps.refresh(a);else WebOps.stop();a.runOnUiThread(this::refresh);},"web-ops-start").start();});server.addView(start);ui.gap(server,8);server.addView(ui.button("Show QR code",()->WebQr.show(a)));
  ui.gap(server,8);server.addView(ui.button("Copy address",()->{String urls=WebOps.urls();if(urls.isEmpty())return;a.getSystemService(android.content.ClipboardManager.class).setPrimaryClip(ClipData.newPlainText("Web Ops",urls));Toast.makeText(a,"Addresses copied",Toast.LENGTH_SHORT).show();}));ui.gap(server,8);server.addView(ui.button("End browser sessions",()->{WebOps.revoke();Toast.makeText(a,"Browser sessions ended",Toast.LENGTH_SHORT).show();}));
  LinearLayout login=card(WebOps.configured(a)?"Change owner login":"Set owner login");login.addView(ui.muted("This login can control your Thor and access shared folders.",16));user=field(login,"Username",false);user.setText(WebOps.prefs(a).getString("user",""));password=field(login,"Password · 12 characters or more",true);confirm=field(login,"Confirm password",true);
  Button save=ui.button("Save login",()->save());login.addView(save);
  LinearLayout certificate=card("Trust this Thor");certificate.addView(ui.muted("1. Export this certificate.\n2. Install and trust it on your other device.\n3. Open the HTTPS address or scan its QR code.\n\nIf Chrome blocks downloads or alerts, finish certificate trust on that computer. The private key stays on the Thor.",16));ui.gap(certificate,10);
  certificate.addView(ui.button("Export browser certificate",()->{Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/x-x509-ca-cert").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"Thor-Web-Ops-CA.crt");a.startActivityForResult(intent,57);}));
  certificate.addView(ui.button("Copy certificate fingerprint",()->new Thread(()->{try{String fingerprint=WebTls.fingerprint(a);a.runOnUiThread(()->{a.getSystemService(android.content.ClipboardManager.class).setPrimaryClip(ClipData.newPlainText("Web Ops certificate SHA-256",fingerprint));Toast.makeText(a,"Fingerprint copied",Toast.LENGTH_SHORT).show();});}catch(Exception e){a.runOnUiThread(()->Toast.makeText(a,"Certificate unavailable",Toast.LENGTH_LONG).show());}},"web-ops-certificate").start()));
  ui.gap(this,8);addView(ui.muted("Monitoring must be running. Active browser use keeps the CPU awake for up to 10 minutes after your last interaction. Allow deep sleep takes priority.",15));refresh();
 }
 private LinearLayout card(String title){LinearLayout c=ui.card(this,null);c.setContentDescription(title);c.setClickable(false);c.setFocusable(false);c.setDescendantFocusability(FOCUS_AFTER_DESCENDANTS);c.addView(ui.text(title,20,true));ui.gap(c,12);return c;}
 private EditText field(LinearLayout parent,String hint,boolean secret){EditText f=new EditText(activity);f.setSingleLine(true);f.setTextColor(ui.p.ink);f.setHintTextColor(ui.p.muted);f.setTextSize(17);f.setHint(hint);f.setContentDescription(hint);f.setInputType(secret?InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD);f.setBackgroundTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_focused},new int[]{}},new int[]{ui.p.accent,ui.p.border}));f.setHighlightColor((ui.p.accent&0x00ffffff)|0x40000000);if(f.getTextCursorDrawable()!=null)f.getTextCursorDrawable().setTint(ui.p.accent);f.setSaveEnabled(false);f.setImportantForAutofill(IMPORTANT_FOR_AUTOFILL_NO);parent.addView(f,new LayoutParams(-1,ui.dp(56)));return f;}
 private void save(){if(saving)return;String name=user.getText().toString().trim();char[] pass=new char[password.length()],second=new char[confirm.length()];password.getText().getChars(0,pass.length,pass,0);confirm.getText().getChars(0,second.length,second,0);
  try{WebSessions.validate(name,pass);if(!Arrays.equals(pass,second))throw new IllegalArgumentException("Passwords do not match");}catch(Exception e){Arrays.fill(pass,'\0');Arrays.fill(second,'\0');Toast.makeText(activity,e.getMessage(),Toast.LENGTH_LONG).show();return;}Arrays.fill(second,'\0');password.setText("");confirm.setText("");saving=true;
  new Thread(()->{String result="Owner login saved";try{WebOps.configure(activity,name,pass);}catch(Exception e){result="Could not save login";}String message=result;activity.runOnUiThread(()->{saving=false;refresh();Toast.makeText(activity,message,Toast.LENGTH_LONG).show();});},"web-ops-owner").start();
 }
 void refresh(){status.setText(!WebOps.configured(activity)?"Set an owner login to begin":!WebOps.error.isEmpty()?WebOps.error:WebOps.running()?"Running · "+WebOps.sessions.count(SystemClock.elapsedRealtime())+" browser sessions\n"+WebOps.summaryUrls():WebOps.enabled(activity)?"Waiting for monitoring":"Stopped");start.setText(WebOps.enabled(activity)?"Stop Web Ops":"Start Web Ops");start.setEnabled(WebOps.configured(activity));}
}
